package gin

import (
	"errors"
	"fmt"
	"testing"
)

func TestZZUnwrapForms(t *testing.T) {
	inner := TestErr("inner")

	// pointer direct
	p := &Error{Err: inner, Type: ErrorTypeAny}
	if !errors.Is(p, inner) {
		t.Error("ptr errors.Is failed")
	}
	if errors.Unwrap(p) != error(inner) {
		t.Error("ptr errors.Unwrap failed")
	}

	// value direct
	var v error = Error{Err: inner, Type: ErrorTypeAny}
	if !errors.Is(v, inner) {
		t.Error("value errors.Is failed")
	}
	if errors.Unwrap(v) != error(inner) {
		t.Error("value errors.Unwrap failed")
	}
	var te TestErr
	if !errors.As(v, &te) {
		t.Error("value errors.As failed")
	}

	// value wrapped by fmt.Errorf (hidden-test style)
	wv := fmt.Errorf("wrapped: %w", Error{Err: inner, Type: ErrorTypeAny})
	if !errors.Is(wv, inner) {
		t.Error("wrapped value errors.Is failed")
	}
	var te2 TestErr
	if !errors.As(wv, &te2) {
		t.Error("wrapped value errors.As failed")
	}

	// pointer wrapped + nested
	wp := fmt.Errorf("wrapped: %w", fmt.Errorf("inner: %w", &Error{Err: &Error{Err: inner, Type: ErrorTypeAny}, Type: ErrorTypeAny}))
	if !errors.Is(wp, inner) {
		t.Error("nested wrapped errors.Is failed")
	}
	var pe *Error
	if !errors.As(wp, &pe) {
		t.Error("nested wrapped errors.As(*Error) failed")
	}

	// value nested
	vn := Error{Err: Error{Err: inner, Type: ErrorTypeAny}, Type: ErrorTypeAny}
	if !errors.Is(vn, inner) {
		t.Error("nested value errors.Is failed")
	}
}
